inductive X3 where | a | b | c
  deriving DecidableEq, Fintype

def choiceFn (S : Finset X3) : Finset X3 :=
  if S = {X3.a, X3.b} then {X3.a}
  else if S = {X3.b, X3.c} then {X3.b}
  else if S = {X3.a, X3.c} then {X3.c}
  else ∅

