variable {X : Type*}

/-- Given a choice structure (ℬ, C(·)), the revealed preference relation ≿*.
    `x ≿* y` iff there exists some budget set `B ∈ ℬ` with `x, y ∈ B` and `x ∈ C(B)`. -/
def RevealedWeakPref (ℬ : Set (Set X)) (C : Set X → Set X) (x y : X) : Prop :=
  ∃ B ∈ ℬ, x ∈ B ∧ y ∈ B ∧ x ∈ C B

import Mathlib

/-- The preference-maximizing choice rule C*(B, ≿).
    Given a relation `ge` (≿) on `X` and a subset `B ⊆ X`,
    returns {x ∈ B | ∀ y ∈ B, x ≿ y}. -/
def preferenceMaximizingChoice {X : Type*} (ge : X → X → Prop) (B : Set X) : Set X :=
  {x ∈ B | ∀ y ∈ B, ge x y}

